<?php
namespace App\Repositories; use App\Core\Database;
final class ServiceRepository extends BaseRepository{protected string $table='services';public function all(int $limit=500):array{$s=Database::pdo()->query('SELECT s.*,COUNT(cs.id) request_count FROM services s LEFT JOIN client_services cs ON cs.service_id=s.id AND cs.status NOT IN ("completed","cancelled") WHERE s.tenant_id=1 AND s.is_active=1 GROUP BY s.id ORDER BY s.name');return $s->fetchAll();}public function findWithRequirements(int $id):?array{$s=$this->find($id);if(!$s)return null;$q=Database::pdo()->prepare('SELECT * FROM service_requirements WHERE service_id=? AND is_active=1 ORDER BY sort_order,id');$q->execute([$id]);$s['requirements']=$q->fetchAll();$q=Database::pdo()->prepare('SELECT * FROM service_automation_profiles WHERE service_id=?');$q->execute([$id]);$s['automation']=$q->fetch()?:[];return $s;}}
